    "css": ".recipe-demo {\\n  display: grid;\\n  gap: 16px;\\n  min-width: 0;\\n}\\n\\n.sample-row {\\n  display: flex;\\n  flex-wrap: wrap;\\n  align-items: center;\\n  gap: 12px;\\n}\\n\\n.sample-card {\\n  min-width: 0;\\n}\\n\\n.radius-none {\\n  border-radius: 0;\\n}\\n\\n.radius-sm {\\n  border-radius: 4px;\\n}\\n\\n.radius-md {\\n  border-radius: 12px;\\n}\\n\\n.radius-lg {\\n  border-radius: 20px;\\n}\\n\\n.radius-pill {\\n  border-radius: 9999px;\\n}\\n\\n.sample-card {\\n  padding: 16px;\\n  border: 1px solid var(--border);\\n}"
