    "css": ".recipe-demo {\\n  display: grid;\\n  gap: 16px;\\n  min-width: 0;\\n}\\n\\n.sample-row {\\n  display: flex;\\n  flex-wrap: wrap;\\n  align-items: center;\\n  gap: 12px;\\n}\\n\\n.sample-card {\\n  min-width: 0;\\n}\\n\\n.sample-title {\\n  font-size: 1.75rem;\\n  font-weight: 700;\\n  line-height: 1.25;\\n}\\n\\n.sample-text {\\n  font-size: 1rem;\\n  font-weight: 400;\\n  line-height: 1.9;\\n}"
