    "css": ".recipe-demo {\\n  display: grid;\\n  gap: 16px;\\n  min-width: 0;\\n}\\n\\n.sample-row {\\n  display: flex;\\n  flex-wrap: wrap;\\n  align-items: center;\\n  gap: 12px;\\n}\\n\\n.sample-card {\\n  min-width: 0;\\n}\\n\\n.sample-grid {\\n  display: grid;\\n  gap: 12px;\\n}\\n@media (min-width: 480px) and (max-width: 767px) {\\n  .sample-grid {\\n    grid-template-columns: repeat(2, minmax(0, 1fr));\\n  }\\n}\\n@media (min-width: 768px) {\\n  .sample-grid {\\n    grid-template-columns: repeat(3, minmax(0, 1fr));\\n  }\\n}"
