    "css": ".recipe-demo {\\n  display: grid;\\n  gap: 16px;\\n  min-width: 0;\\n}\\n\\n.sample-row {\\n  display: flex;\\n  flex-wrap: wrap;\\n  align-items: center;\\n  gap: 12px;\\n}\\n\\n.sample-card {\\n  min-width: 0;\\n}\\n\\n.sample-details {\\n  border: 1px solid var(--border);\\n  border-radius: 12px;\\n  padding: 16px;\\n}\\n\\n.sample-details summary {\\n  cursor: pointer;\\n  font-weight: 600;\\n}\\n\\n.sample-details[open] {\\n  background: var(--soft);\\n}\\n\\n.sample-details p {\\n  margin-block-start: 12px;\\n}"
