    "css": ".recipe-demo {\\n  display: grid;\\n  gap: 16px;\\n  min-width: 0;\\n}\\n\\n.sample-row {\\n  display: flex;\\n  flex-wrap: wrap;\\n  align-items: center;\\n  gap: 12px;\\n}\\n\\n.sample-card {\\n  min-width: 0;\\n}\\n\\n.sample-parent {\\n  container-name: recipe;\\n  container-type: inline-size;\\n}\\n\\n.sample-grid {\\n  display: grid;\\n  gap: 12px;\\n}\\n@container recipe (min-width: 480px) {\\n  .sample-grid {\\n    grid-template-columns: 1fr 1fr;\\n  }\\n}"
